    document.querySelectorAll('.avatar-option').forEach(el => el.classList.remove('selected'));

    // Add new selection
    element.classList.add('selected');
    selectedAvatar = filename;

    validateIdentityStep();
}

function validateIdentityStep() {
    const name = nicknameInput.value.trim();
    if (name.length > 0 && selectedAvatar) {
        nextBtn.removeAttribute('disabled');
    } else {
        nextBtn.setAttribute('disabled', 'true');
    }
}

// Event Listeners for Identity Step
nicknameInput.addEventListener('input', validateIdentityStep);

nextBtn.addEventListener('click', () => {
    // Save to LocalStorage
    const userState = {
        nickname: nicknameInput.value.trim(),
        avatar: selectedAvatar
    };
    localStorage.setItem('serenity_user', JSON.stringify(userState));

    // Check for room in URL or Stored
    const urlParams = new URLSearchParams(window.location.search);
    const roomLink = urlParams.get('room');
    const storedRoom = localStorage.getItem('serenity_room');

    // Priority: URL Param > Stored > Selection UI
    if (roomLink) {
        enterRoom(roomLink);
    } else if (storedRoom) {
        enterRoom(storedRoom);
    } else {
        // Transition to Room Step
        stepIdentity.style.display = 'none';
        stepRoom.style.display = 'block';
    }
});

// Event Listeners for Room Step
roomIdInput.addEventListener('input', () => {
    const val = roomIdInput.value.trim();
    if (val.length > 0) {
        enterBtn.removeAttribute('disabled');
    } else {
        enterBtn.setAttribute('disabled', 'true');
    }
});

function enterRoom(roomId) {
    const user = JSON.parse(localStorage.getItem('serenity_user'));
    socket.emit('join-room', { roomId, user });
}

function createRoom(roomId) {
    const user = JSON.parse(localStorage.getItem('serenity_user'));
    socket.emit('create-room', { roomId, user });
}

socket.on('room-created', (roomId) => {
    localStorage.setItem('serenity_room', roomId);
    window.location.href = `/room.html?id=${encodeURIComponent(roomId)}`;
});

socket.on('room-not-found', (message) => {
    const roomId = roomIdInput.value.trim() || localStorage.getItem('serenity_room');
    showConfirm('Room Not Found', message, () => {
        createRoom(roomId);
    });
});

socket.on('room-error', (message) => {
    showAlert('Error', message);
});

enterBtn.addEventListener('click', () => {
    enterRoom(roomIdInput.value.trim());
});

createBtn.addEventListener('click', () => {
    // Unique Room Name Logic: Cute Adjective + Noun + Timestamp Suffix
    const adjectives = ['Cozy', 'Quiet', 'Soft', 'Focus', 'Dreamy', 'Sunny', 'Zen', 'Calm'];
    const nouns = ['Nook', 'Den', 'Corner', 'Space', 'Garden', 'Cafe', 'Studio', 'Lounge'];

    const base = adjectives[Math.floor(Math.random() * adjectives.length)] +
                 nouns[Math.floor(Math.random() * nouns.length)];

    // Add a short random suffix to ensure uniqueness even if two people click at once
    const suffix = Math.random().toString(36).substring(2, 5).toUpperCase();
    const uniqueRoomName = `${base}-${suffix}`;

    createRoom(uniqueRoomName);
});

// --- HELPER UI (Simplified for Landing) ---
function showConfirm(title, message, onConfirm) {
    // If we have access to a modal in index.html, we'd use it. 
    // Since index.html might not have the same modal as room.html yet, 
    // let's use a standard confirm for now or ensure index.html has it.
    if (window.confirm(`${title}\n\n${message}`)) {
        onConfirm();
    }
}

function showAlert(title, message) {
    window.alert(`${title}\n\n${message}`);
}

// Initialize
initAvatars();

if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
    navigator.serviceWorker.controller.postMessage({
        type: 'CACHE_PRIORITY',
        urls: ['/assets/desk.webp?v=8']
    });
}

// Check for room link immediately
const urlParams = new URLSearchParams(window.location.search);
const roomFromUrl = urlParams.get('room');
if (roomFromUrl) {
    // We don't join yet, but we store it so we skip the room selection UI later
    localStorage.setItem('serenity_room', roomFromUrl);
    // Optional: Update UI to show we are joining a specific room? 
    // For now we just keep it silent until they hit "Continue"
} else {
    // If no room in URL, clear any stale room from previous sessions
    localStorage.removeItem('serenity_room');
}

// Ensure fresh identity BUT keep the room if we just clicked a link
localStorage.removeItem('serenity_user');



// --- SECURITY & DEV MODE ---
// DevTools and Right-click are now enabled as requested.

